Object.assign(window.deepArticles,{
  "burma":burmeseArticle({
    title:"Union of Burma",category:"Countries",eyebrow:"Sovereign associated union · Thai security protectorate",infoboxKicker:"Bamar-led asymmetric federation",
    flag:{src:"assets/flags/burma-1948.svg",alt:"Flag of the Union of Burma",caption:"The 1948–1962 Burmese flag is retained by the Union through its successive constitutional settlements"},
    lead:"The Union of Burma is a formally sovereign, Bamar-led federal state assembled from the Irrawaddy core, seven constituent nationality states, and nested autonomous frontier districts. Britain recovered the country before the 1947 peace, lost its protectorate during the Burmese Companion War, and yielded to a Japanese-guaranteed federal settlement that repeatedly broke and re-formed before a mid-1990s Thai security protectorate.",
    canon:"British recovery and postwar protection; the 1948–1953 Companion War; 1952–1953 Rangoon Settlement; 1954–1956 Federal Crisis; later Second Burmese War, Sovereign States Experiment, War of the Burmese States; and mid-1990s Thai protectorate are established. Exact later dates, leaders, borders, treaty names, and campaign sequences remain open.",
    sections:[
      {id:"british",title:"British recovery and overload",html:"<p>Commonwealth and Indian forces recover Burma late in the Second World War, one of Japan's few clear theater defeats. After the Breaking of the Raj, Rangoon becomes a rear headquarters and evacuation port crowded with British civilians, Anglo-Indians, Indian troops, refugees, stores, and failing imperial institutions.</p>"},
      {id:"companion",title:"The Burmese Companion War",html:"<p>The <a href='burmese-companion-war.html'>1948–1953 war</a> joins the British-protected Rangoon government, frontier and nationality armies, communist and radical Bamar forces, and Japanese-backed nationalists. Japan shifts from supporting overthrow to brokering transfer because destroying the recognized government would leave Tokyo responsible for rebuilding the country.</p>"},
      {id:"rangoon",title:"The Rangoon Settlement",html:"<p>The <a href='rangoon-settlement.html'>1952–1953 package</a> ends British protection, preserves one international Union, recognizes constituent states and State Guards, installs Japanese security association, and protects evacuation, residency, and property rights. It is the first ceasefire constitution rather than a final peace.</p>"},
      {id:"federal",title:"One Union, several national governments",html:"<p>The <a href='bamar-union-core.html'>Bamar core</a> directly governs Rangoon, Mandalay, the delta, central lowlands, and the principal transport spine. <a href='shan-state.html'>Shan</a>, <a href='kachin-state.html'>Kachin</a>, <a href='chin-state.html'>Chin</a>, <a href='karen-state.html'>Karen</a>, <a href='karenni-state.html'>Karenni</a>, <a href='mon-state.html'>Mon</a>, and <a href='arakan-state.html'>Arakan</a> retain unequal internal association.</p>"},
      {id:"armed",title:"Armed federalism",html:"<p>The <a href='armed-federalism-burma.html'>Union Army</a> controls armor, artillery, aviation, arsenals, and strategic communications; constituent State Guards control local infantry, scouts, gendarmerie, and ordinary security. Japanese command over modern supply prevents both total Bamar conquest and unilateral secession.</p>"},
      {id:"wars",title:"Repeated constitutional wars",html:"<p>The <a href='burmese-federal-crisis.html'>Federal Crisis</a>, <a href='second-burmese-war.html'>Second Burmese War</a>, <a href='sovereign-states-experiment.html'>Sovereign States Experiment</a>, and <a href='war-of-burmese-states.html'>War of the Burmese States</a> test every solution from deeper union to international partition. Each fails because populations, ports, rivers, railways, and armed institutions cannot be separated cleanly.</p>"},
      {id:"economy",title:"Corridor economy",html:"<p>Rice and the Irrawaddy spine support the center; Thai-facing southeastern corridors carry timber and trade; northern routes carry minerals and military traffic; western frontiers cost more than they yield. Japanese corporate power is substantial but usually mediated through generals, State Guards, port authorities, development foundations, and Thai partners.</p>"},
      {id:"protectorate",title:"The Thai security protectorate",html:"<p>In the mid-1990s Japan authorizes a <a href='thai-protectorate-burma.html'>Thai protectorate</a>. Burma keeps its flag, citizenship, governments, and constituent institutions while Thailand controls common security, heavy weapons, alignment, strategic transport, and daily arbitration beneath ultimate Japanese guarantee.</p>"}
    ],
    related:[{href:"burmese-wars.html",kicker:"Conflict history",label:"Burmese Wars and Settlements"},{href:"rangoon-settlement.html",kicker:"Founding settlement",label:"Rangoon Settlement"},{href:"armed-federalism-burma.html",kicker:"Security constitution",label:"Armed Federalism"},{href:"thai-protectorate-burma.html",kicker:"Mature order",label:"Thai Protectorate over Burma"}],
    facts:[["Capital","Rangoon"],["Government","Asymmetric federal guardian republic"],["Sovereignty","Formally sovereign"],["Constituent states","Seven"],["State language","Burmese; protected constituent languages"],["External security","Thai protectorate under Japanese guarantee"],["Founding settlement","Rangoon Settlement, 1952–1953"],["National flag","1948 Union flag retained"]]
  }),

  "burmese-wars":burmeseArticle({
    title:"Burmese Wars and Settlements",category:"Conflict histories",eyebrow:"Recurring federal wars · 1948–mid-1990s",infoboxKicker:"Burmese constitutional conflict cycle",flag:{src:"assets/diagrams/burmese-war-cycle.svg",alt:"Timeline of the Burmese war and settlement cycle",caption:"The founding dates are fixed; later war dates and treaty titles remain deliberately open"},
    lead:"The Burmese wars were the recurring conflicts through which a British-protected rear area became a Japanese-associated Union, fragmented into sovereign nationality states, returned to one international framework, and ultimately entered Thai security protection. They share a constitutional question rather than one continuous front: who governs the frontier, commands armed institutions, controls transit, and receives revenue.",canon:"The order and broad content of five phases are established. The Companion War and first two settlement dates are fixed; exact dates, leaders, battles, treaty titles, and duration of the later phases remain open under P1-32.",
    sections:[
      {id:"companion",title:"Burmese Companion War, 1948–1953",html:"<p>The <a href='burmese-companion-war.html'>founding war</a> begins as Britain's Burmese rear area fractures during India's collapse. Japan obtains political predominance through selective support and negotiation rather than an uninterrupted occupation or complete reconquest.</p>"},
      {id:"rangoon",title:"Rangoon Settlement, 1952–1953",html:"<p>The <a href='rangoon-settlement.html'>settlement package</a> terminates British protection, recognizes an asymmetric Union, legalizes State Guards, and gives Japan final influence over modern supply and constitutional security.</p>"},
      {id:"federal",title:"Federal Crisis, 1954–1956",html:"<p>Rangoon's attempts to standardize taxation, education, transport, appointments, and armed forces appear as Bamar consolidation. The <a href='burmese-federal-crisis.html'>crisis</a> deepens federal guarantees and gives Thailand a larger stabilization role.</p>"},
      {id:"second",title:"Second Burmese War",html:"<p>A later-1960s dispute over the nature of the Union brings several State Guards into simultaneous mobilization. Japan and Thailand prevent Rangoon from conquering the frontier and refuse to recognize unilateral secession.</p>"},
      {id:"experiment",title:"Sovereign States Experiment",html:"<p>The <a href='sovereign-states-experiment.html'>Union is temporarily dissolved or reduced</a> while Bamar, Shan, Kachin, Chin, Karen, Karenni, Mon, and Arakan governments receive international statehood under common transit and defense restrictions.</p>"},
      {id:"stateswar",title:"War of the Burmese States",html:"<p>Border posts, tolls, minority militias, roads, ports, rivers, and protected districts turn formal separation into interstate war. A Japanese–Thai stabilization force secures strategic nodes and restores one international Burmese personality.</p>"},
      {id:"later",title:"Local, regional, and Union crises",html:"<p>Later violence ranges from days-long checkpoint incidents to months-long corridor wars and rare crises threatening Rangoon or common currency. Thailand normally mediates first; Japan intervenes when international alignment or the Union's survival is at stake.</p>"},
      {id:"protectorate",title:"Protectorate settlement",html:"<p>By the mid-1990s exhaustion and delegated Japanese strategy produce the <a href='thai-protectorate-burma.html'>Thai security protectorate</a>. The arrangement freezes escalation more reliably than any previous constitution without dissolving the armed national governments.</p>"}
    ],related:[{href:"burma.html",kicker:"State history",label:"Union of Burma"},{href:"burmese-companion-war.html",kicker:"Founding conflict",label:"Burmese Companion War"},{href:"sovereign-states-experiment.html",kicker:"Partition experiment",label:"Sovereign States Experiment"},{href:"thai-protectorate-burma.html",kicker:"Final working settlement",label:"Thai Protectorate over Burma"}],facts:[["First conflict","Burmese Companion War, 1948–1953"],["First settlement","Rangoon Settlement, 1952–1953"],["First postwar crisis","Federal Crisis, 1954–1956"],["Later major war","Second Burmese War"],["Partition phase","Sovereign States Experiment"],["Interstate conflict","War of the Burmese States"],["Mature settlement","Thai protectorate, mid-1990s"],["Later exact chronology","Open"]]
  }),

  "bamar-union-core":burmeseArticle({
    title:"Bamar Union Core",category:"Regions and governments",eyebrow:"Direct Union territory · Irrawaddy valley",infoboxKicker:"Central Burmese national government",flag:{src:"assets/diagrams/burmese-federal-architecture.svg",alt:"Burmese federal architecture",caption:"The Union core is not called a Bamar state because the central government already performs that function"},
    lead:"The Bamar Union Core is the directly governed central territory of Burma: Rangoon, Mandalay, the Irrawaddy delta and valley, the central dry zone, principal ports, ministries, railways, and river system. It is legally the common government of all citizens and functionally the Bamar national state within the federation.",canon:"The direct central territory, demographic and institutional imbalance, Bamar command culture, and control of common machinery are established. Exact internal boundary, capital arrangements during the Sovereign States Experiment, and later constitutional terminology remain open.",
    sections:[
      {id:"territory",title:"Irrawaddy heartland",html:"<p>The core contains the delta, central lowlands, Rangoon, Mandalay, major ports, the main railway, and the national river spine. It holds the largest population, tax base, bureaucracy, and consumer market.</p>"},
      {id:"claim",title:"Union claim and Bamar reality",html:"<p>Rangoon insists that the central government belongs to every Burmese citizen. Frontier leaders answer that Burmese language, Buddhist symbolism, senior ministries, education, media, and army command make it the Bamar state under a federal title.</p>"},
      {id:"government",title:"National ministries",html:"<p>Foreign affairs, currency, customs, strategic taxation, aviation, heavy forces, railways, river transport, and Japanese treaties are administered from the core.</p>"},
      {id:"army",title:"Home of the Union Army",html:"<p>The central officer academy, arsenals, strategic reserves, armor, artillery, aviation, and communications are concentrated around Rangoon, Mandalay, and the transport corridors.</p>"},
      {id:"economy",title:"Rice, ports, and national commerce",html:"<p>Delta rice, river trade, ports, administration, consumer markets, and the largest Burmese-owned firms finance common government. Frontier states regard their own resource royalties as protection against this economic weight.</p>"},
      {id:"minorities",title:"Minorities inside the core",html:"<p>Karen communities in the delta, urban Indian and Chinese populations, Anglo-Burmese residents, and other groups prevent the heartland from being ethnically uniform. Protected districts and property arrangements complicate direct rule.</p>"},
      {id:"experiment",title:"Bamar Burma in the partition experiment",html:"<p>During the <a href='sovereign-states-experiment.html'>Sovereign States Experiment</a>, the core becomes Bamar Burma and retains Rangoon, the central bank, bureaucracy, and much of the old army. That inheritance convinces other states that separation may be temporary.</p>"},
      {id:"position",title:"Position in the mature protectorate",html:"<p>The core remains the Union's international face while Thai and Japanese guarantees restrict its freedom to move heavy forces into constituent territory or convert common institutions into unilateral Bamar authority.</p>"}
    ],related:[{href:"burma.html",kicker:"Sovereign framework",label:"Union of Burma"},{href:"armed-federalism-burma.html",kicker:"Central force",label:"Armed Federalism"},{href:"rangoon-settlement.html",kicker:"Constitutional foundation",label:"Rangoon Settlement"},{href:"sovereign-states-experiment.html",kicker:"Temporary sovereign form",label:"Sovereign States Experiment"}],facts:[["Administrative center","Rangoon"],["Second national center","Mandalay"],["Territory","Irrawaddy delta, valley, and central lowlands"],["Principal nationality","Bamar"],["Common language","Burmese"],["Economic base","Rice, ports, river trade, and administration"],["Armed institution","Union Army"],["Legal claim","Common government of all Burmese citizens"]]
  }),

  "shan-state":burmeseArticle({
    title:"Federated Shan State",category:"Constituent states",infoboxKicker:"Most autonomous Burmese constituent state",flag:{src:"assets/diagrams/burmese-federal-architecture.svg",alt:"Burmese federal architecture",caption:"Shan State is itself federal and contains several protected non-Shan districts"},
    lead:"The Federated Shan State is Burma's most autonomous constituent government, joining Shan principalities and administrative regions with protected Wa, Pa-O, Ta’ang/Palaung, Kokang, and other districts. It balances Rangoon's strategic corridors against Thai cultural and commercial influence and Japanese guarantees.",canon:"Deep autonomy, internal federalism, State Council, hereditary or successor institutions, State Guard, Thai influence, and Japanese balancing are established. Formal title, capital, borders, officeholders, and status during later wars remain open.",
    sections:[
      {id:"formation",title:"Principalities inside a federation",html:"<p>The Shan country enters the modern Union through hereditary states, valleys, towns, uplands, and armed institutions rather than one centralized ethnic province.</p>"},
      {id:"council",title:"State Council and regional representation",html:"<p>Sawbwas or their constitutional successors sit beside elected, corporative, and regional delegates. The council governs land, education, culture, local taxation, and ordinary administration.</p>"},
      {id:"districts",title:"Nested autonomous districts",html:"<p>Wa, Pa-O, Ta’ang/Palaung, Kokang, and other communities retain councils, schooling, land law, and local security. Shan autonomy cannot lawfully reproduce Bamar centralization at a lower level.</p>"},
      {id:"guard",title:"Shan State Guard",html:"<p>The Guard provides infantry, border security, and internal policing while heavy artillery, aviation, and designated corridors remain Union responsibilities.</p>"},
      {id:"thailand",title:"Thai influence",html:"<p>Thai universities, Buddhist institutions, merchants, transport firms, intelligence networks, and frontier officers operate throughout the east. Bangkok invokes wider Tai affinity without formally annexing the state.</p>"},
      {id:"japan",title:"Japanese balance",html:"<p>Japan prevents Rangoon from absorbing the Shan system and prevents Thailand from turning it into a direct protectorate. Shan leaders preserve autonomy by navigating both external powers.</p>"},
      {id:"wars",title:"Role in the Burmese wars",html:"<p>Shan mobilization is central to the Federal Crisis and Second Burmese War. During sovereign separation, smaller peoples challenge the claim that the old Shan boundary should become an international nation-state.</p>"},
      {id:"position",title:"Position under the protectorate",html:"<p>The mature Thai protectorate increases daily Bangkok influence but leaves sovereignty formally Burmese and final strategic authority Japanese.</p>"}
    ],related:[{href:"burma.html",kicker:"Federal sovereign",label:"Union of Burma"},{href:"armed-federalism-burma.html",kicker:"Security system",label:"Armed Federalism"},{href:"sovereign-states-experiment.html",kicker:"Sovereign phase",label:"Sovereign States Experiment"},{href:"thailand.html",kicker:"Eastern influence",label:"Kingdom of Thailand"}],facts:[["Government","Federated constituent state"],["Capital","Open"],["Internal institutions","State Council and regional successors to the sawbwas"],["Protected districts","Wa, Pa-O, Ta’ang/Palaung, Kokang, and others"],["Armed force","Shan State Guard"],["Union retains","Foreign policy, heavy weapons, aviation, and strategic corridors"],["Principal external influence","Thailand"],["Strategic guarantor","Japan"]]
  }),

  "kachin-state":burmeseArticle({
    title:"Kachin State",category:"Constituent states",infoboxKicker:"Northern military-frontier state",flag:{src:"assets/diagrams/burmese-federal-architecture.svg",alt:"Burmese federal architecture",caption:"Military experience, mountain geography, Christian institutions, and resource districts sustain Kachin autonomy"},
    lead:"Kachin State is the northern military-frontier constituent state of Burma. British-trained service traditions, Christian institutions, local chiefs, inaccessible terrain, and control of timber, jade, minerals, and hydroelectric sites give its State Guard and government exceptional bargaining power.",canon:"The northern autonomy, strong light infantry, liaison restrictions on Union entry, resource conflicts, Christian institutions, and Japanese guarantee are established. Borders, capital, official title, and internal constituent map remain open.",
    sections:[
      {id:"formation",title:"Military frontier identity",html:"<p>Kachin political identity is strengthened by wartime recruitment, mountain defense, mission schools, local authority, and suspicion of Bamar Buddhist nationalism.</p>"},
      {id:"government",title:"Chiefs, councils, and modern ministries",html:"<p>Local chieftaincies and regional councils coexist with a state government responsible for education, land, policing, and concessions.</p>"},
      {id:"guard",title:"Kachin State Guard",html:"<p>The Guard is one of Burma's best light-infantry forces, specializing in mountain patrol, reconnaissance, border security, and local counterinsurgency.</p>"},
      {id:"liaison",title:"Limits on Union deployment",html:"<p>Union artillery, aviation, and corridor bases remain in the north, but ordinary entry into Kachin districts requires notification and liaison rather than unrestricted central command.</p>"},
      {id:"resources",title:"Timber, jade, minerals, and power",html:"<p>Japanese firms seek extraction and hydroelectric projects. The state demands royalties, local employment, land protection, and limits on Bamar settlement.</p>"},
      {id:"frontiers",title:"China and Indian approaches",html:"<p>Smuggling, refugees, military traffic, and mountain routes link the state to Chinese and Indian frontier systems. Strategic depth often matters more than tax revenue.</p>"},
      {id:"wars",title:"Federal conflict",html:"<p>Kachin resistance to guard integration and resource centralization helps drive repeated federal crises. Sovereign statehood later proves unable to settle internal districts or shared transport.</p>"},
      {id:"position",title:"Position by the protectorate era",html:"<p>Kachin State remains heavily armed locally but dependent on Japanese supply and common Burmese recognition. Thailand's influence is weaker than in Shan and Karen country.</p>"}
    ],related:[{href:"burma.html",kicker:"Federal sovereign",label:"Union of Burma"},{href:"armed-federalism-burma.html",kicker:"Military constitution",label:"Armed Federalism"},{href:"shan-state.html",kicker:"Eastern neighbor",label:"Federated Shan State"},{href:"burmese-federal-crisis.html",kicker:"Constitutional conflict",label:"Federal Crisis"}],facts:[["Government","Autonomous constituent state"],["Capital","Open"],["Political foundations","Military service, chiefs, churches, and mountain geography"],["Armed force","Kachin State Guard"],["Military specialization","Mountain light infantry and reconnaissance"],["Major resources","Timber, jade, minerals, and hydroelectric potential"],["Union deployment","Subject to corridor and liaison rules"],["Strategic guarantor","Japan"]]
  }),

  "chin-state":burmeseArticle({
    title:"Chin State",category:"Constituent states",infoboxKicker:"Subsidized western frontier federation",flag:{src:"assets/diagrams/burmese-federal-architecture.svg",alt:"Burmese federal architecture",caption:"Chin autonomy is broad in local affairs and weak in finance, transport, and strategic independence"},
    lead:"Chin State is the poor and mountainous western constituent state governed through district councils, chiefs, churches, schools, local administrators, and a lightly armed frontier guard. Its continued attachment to Burma provides strategic depth against the Indian wars.",canon:"The council-based administration, Christian and customary institutions, subsidy dependence, local guard, Japanese aviation and communications support, and Indian-frontier role are established. Capital, exact borders, formal title, and Naga boundary remain open.",
    sections:[
      {id:"formation",title:"A district federation",html:"<p>Scattered highland communities and difficult communications make a powerful centralized ministry impractical. The state is an accumulation of councils and local authorities beneath a federal framework.</p>"},
      {id:"government",title:"Councils, chiefs, and churches",html:"<p>District councils, customary leaders, churches, schools, and administrators govern land, education, family matters, and community life.</p>"},
      {id:"economy",title:"Poverty and subsidy",html:"<p>Thin markets, poor roads, limited industry, and high transport cost make Union and Japanese subsidies essential. Strategic expense frequently exceeds local tax revenue.</p>"},
      {id:"guard",title:"Frontier Guard",html:"<p>A lightly armed State Guard and local scouts monitor passes, refugees, smugglers, and armed movements without possessing independent heavy forces.</p>"},
      {id:"india",title:"Exposure to the Indian wars",html:"<p>Refugees, weapons, political movements, and military spillover cross the western hills. Subsidized airfields and restricted travel are treated as security institutions rather than ordinary development.</p>"},
      {id:"naga",title:"The Naga frontier",html:"<p>Naga districts generally remain separately autonomous or under a Northwestern Frontier arrangement rather than being absorbed unconditionally into Chin government.</p>"},
      {id:"wars",title:"Survival through the war cycle",html:"<p>Chin forces participate in larger constitutional conflicts but rarely seek regional supremacy. During sovereign partition, weak finance makes formal independence especially dependent on Japanese support.</p>"},
      {id:"position",title:"Position under Thai protection",html:"<p>Thai influence is indirect and logistical; Japan remains the decisive sponsor. Chin autonomy survives because neither Rangoon nor Bangkok wants to administer the hills directly.</p>"}
    ],related:[{href:"burma.html",kicker:"Federal sovereign",label:"Union of Burma"},{href:"armed-federalism-burma.html",kicker:"Security structure",label:"Armed Federalism"},{href:"arakan-state.html",kicker:"Southwestern neighbor",label:"Arakan State"},{href:"india-successors.html",kicker:"Western strategic context",label:"Indian Successor States"}],facts:[["Government","Federation of district councils"],["Capital","Open"],["Core institutions","Chiefs, churches, schools, and local councils"],["Armed force","Light State Guard and border scouts"],["Economic position","Subsidy-dependent"],["Principal strategic role","Buffer against Indian-war spillover"],["Naga districts","Separately autonomous or frontier-administered"],["Principal guarantor","Japan"]]
  }),

  "karen-state":burmeseArticle({
    title:"Karen State",category:"Constituent states",infoboxKicker:"Southeastern territorial Karen state",flag:{src:"assets/diagrams/burmese-federal-architecture.svg",alt:"Burmese federal architecture",caption:"A frontier Karen State coexists with protected Karen districts inside the Bamar delta"},
    lead:"Karen State is the recognized southeastern Karen constituent state along the Salween and Thai frontier. Because large Karen communities remain in the Irrawaddy delta and lower Burma, its territorial government is paired with protected districts, schools, churches, land associations, and Union representation outside its borders.",canon:"The southeastern territorial state, two-part settlement, State Guard, religious protections, Thai access, and persistent delta grievance are established. Whether Kawthoolei becomes the official name, and the exact borders and capital, remain open.",
    sections:[
      {id:"problem",title:"A dispersed nationality",html:"<p>No clean border can include frontier and delta Karen communities without dividing the Bamar heartland and approaches to Rangoon.</p>"},
      {id:"state",title:"The southeastern state",html:"<p>The territorial state possesses an assembly, language education, Christian and Buddhist protections, substantial administration, and treaty-regulated access to Thailand.</p>"},
      {id:"delta",title:"Protected delta districts",html:"<p>Karen communities outside the state retain schools, churches and monasteries, councils, land protections, language rights, and representation rather than territorial transfer.</p>"},
      {id:"guard",title:"Karen State Guard",html:"<p>The Guard provides frontier infantry, local security, and organized armed identity. It cannot lawfully acquire combat aircraft or independent heavy supply.</p>"},
      {id:"thailand",title:"Thai frontier relationship",html:"<p>Trade, refuge, transport, churches, intelligence, and military liaison tie the state closely to Thailand. Japan limits Bangkok's ability to turn those ties into a direct protectorate before the wider mid-1990s settlement.</p>"},
      {id:"grievance",title:"The incomplete national settlement",html:"<p>Karen nationalists regard the delta arrangement as division of one people. Rangoon regards transfer of delta territory as incompatible with survival of the capital and national rice economy.</p>"},
      {id:"wars",title:"Centrality in repeated wars",html:"<p>Karen forces are major participants in the Companion War, Federal Crisis, Second Burmese War, and sovereign-state phase. Port and corridor disputes with Bamar and Mon governments persist after partition.</p>"},
      {id:"position",title:"Position under the protectorate",html:"<p>Thai protection strengthens daily frontier leverage but does not unite all Karen communities or erase Japanese final arbitration.</p>"}
    ],related:[{href:"burma.html",kicker:"Federal sovereign",label:"Union of Burma"},{href:"karenni-state.html",kicker:"Smaller eastern neighbor",label:"Karenni State"},{href:"mon-state.html",kicker:"Southeastern neighbor",label:"Mon State"},{href:"thai-protectorate-burma.html",kicker:"Mature security order",label:"Thai Protectorate over Burma"}],facts:[["Government","Autonomous constituent state"],["Capital","Open"],["Territory","Southeastern frontier and Salween region"],["External communities","Protected Karen districts in the delta and lower Burma"],["Armed force","Karen State Guard"],["Religious protections","Christian and Buddhist"],["Alternative national name","Kawthoolei; official status open"],["Principal external influence","Thailand"]]
  }),

  "karenni-state":burmeseArticle({
    title:"Karenni State",category:"Constituent states",infoboxKicker:"Small princely frontier state",flag:{src:"assets/diagrams/burmese-federal-architecture.svg",alt:"Burmese federal architecture",caption:"Compact territory and inherited princely institutions make Karenni easier to preserve separately than to merge"},
    lead:"Karenni State is the small eastern constituent state whose compact territorial identity, princely traditions, and local armed institutions survive every Burmese constitutional reconstruction. It remains distinct from the larger and geographically dispersed Karen settlement.",canon:"Separate Karenni statehood, princely or successor institutions, local law, State Guard, and compact frontier identity are established. Capital, dynasty, constitutional title, flag, and precise borders remain open.",
    sections:[
      {id:"identity",title:"A compact inherited territory",html:"<p>Karenni enters the postwar order with clearer territorial and princely foundations than the wider Karen claim, making separate recognition administratively easier.</p>"},
      {id:"government",title:"Rulers and constitutional successors",html:"<p>Local rulers or successor institutions govern beside councils and a small modern administration. Their exact postwar legal form remains unsettled.</p>"},
      {id:"law",title:"Internal legal autonomy",html:"<p>The state controls local administration, customary law, land, education, religion, and ordinary policing beneath Union restrictions on foreign policy and heavy weapons.</p>"},
      {id:"guard",title:"Karenni State Guard",html:"<p>A small Guard provides border security and the armed guarantee of autonomy. Its size limits independent power while making forced absorption politically costly.</p>"},
      {id:"economy",title:"A small frontier economy",html:"<p>Agriculture, forest routes, local trade, and transport links provide a narrow base. Union, Thai, and Japanese infrastructure support is consequential.</p>"},
      {id:"neighbors",title:"Between Shan, Karen, and the core",html:"<p>Border and transit questions tie Karenni to larger neighbors whose forces and claims could easily overwhelm it without external guarantees.</p>"},
      {id:"experiment",title:"Sovereign-state phase",html:"<p>International sovereignty gives Karenni formal equality without eliminating dependence on common roads, currency clearing, and security restrictions.</p>"},
      {id:"position",title:"Position in the mature Union",html:"<p>Karenni's survival is one of the clearest examples of Japan preserving a small national institution because amalgamation offers fewer strategic benefits than continued autonomy.</p>"}
    ],related:[{href:"karen-state.html",kicker:"Larger nationality neighbor",label:"Karen State"},{href:"shan-state.html",kicker:"Northern neighbor",label:"Federated Shan State"},{href:"burma.html",kicker:"Federal sovereign",label:"Union of Burma"},{href:"sovereign-states-experiment.html",kicker:"Sovereign phase",label:"Sovereign States Experiment"}],facts:[["Government","Small autonomous constituent state"],["Capital","Open"],["Political foundation","Inherited princely territory"],["Armed force","Karenni State Guard"],["Internal authority","Land, custom, education, and policing"],["Foreign policy","Union-controlled"],["Economic base","Agriculture and frontier trade"],["Strategic guarantor","Japan; later Thai security protection"]]
  }),

  "mon-state":burmeseArticle({
    title:"Mon State",category:"Constituent states",infoboxKicker:"Lower southeastern coastal state",flag:{src:"assets/diagrams/burmese-federal-architecture.svg",alt:"Burmese federal architecture",caption:"Mon autonomy emphasizes language and municipal culture while Rangoon retains strategic port and railway authority"},
    lead:"Mon State is the lower southeastern constituent state around Moulmein, Thaton, and the coastal corridor. Its autonomy centers on language, Buddhist history, schools, archaeology, broadcasting, and municipal government more than permanent heavy militarization.",canon:"The Moulmein–Thaton coastal state, cultural-administrative emphasis, smaller State Guard, and Union control of ports, railways, roads, and bases are established. Exact boundary, capital title, and status in later settlements remain open.",
    sections:[
      {id:"formation",title:"From cultural movement to statehood",html:"<p>Mon institutions are deeply integrated into the lowland economy, so demands initially emphasize language and administration before recurring conflict produces recognized statehood.</p>"},
      {id:"territory",title:"Moulmein, Thaton, and the coast",html:"<p>The state occupies the lower southeastern coast and river approaches. Moulmein is its political and cultural center and a strategic Union port.</p>"},
      {id:"culture",title:"Language and historical institutions",html:"<p>Schools, Buddhist history, archaeology, publishing, broadcasting, and municipal life protect Mon identity against absorption into the Burmese-speaking center.</p>"},
      {id:"security",title:"A smaller State Guard",html:"<p>Mon security forces are lighter than Shan, Kachin, or Karen formations. Their principal roles are policing, local defense, and protection of state institutions.</p>"},
      {id:"union",title:"Union strategic rights",html:"<p>Rangoon retains stronger authority over Moulmein port, railways, military roads, and Japanese naval and air facilities than in more remote frontier states.</p>"},
      {id:"economy",title:"Ports and the southeastern corridor",html:"<p>Shipping, trade, transport, fisheries, agriculture, and Thai-facing commerce link Mon territory to Rangoon, Singapore, and Thailand.</p>"},
      {id:"wars",title:"Mon–Karen and Bamar disputes",html:"<p>During sovereign separation, Mon and Karen claims overlap across ports, roads, and valleys. The state cannot remain economically independent of shared southeastern infrastructure.</p>"},
      {id:"position",title:"Position under Thai protection",html:"<p>Thai commercial influence grows while common ports and bases remain subject to Japanese-backed Union agreements. Cultural autonomy survives more fully than strategic autonomy.</p>"}
    ],related:[{href:"karen-state.html",kicker:"Eastern and northern neighbor",label:"Karen State"},{href:"burma.html",kicker:"Federal sovereign",label:"Union of Burma"},{href:"war-of-burmese-states.html",kicker:"Interstate conflict",label:"War of the Burmese States"},{href:"thai-protectorate-burma.html",kicker:"Mature order",label:"Thai Protectorate over Burma"}],facts:[["Political center","Moulmein"],["Historic center","Thaton"],["Government","Autonomous constituent state"],["Autonomy emphasis","Language, history, schools, broadcasting, and municipalities"],["Armed force","Small Mon State Guard"],["Union retains","Ports, railways, strategic roads, and major bases"],["Economic position","Southeastern trade corridor"],["Principal external influence","Thailand"]]
  }),

  "arakan-state":burmeseArticle({
    title:"Arakan State",category:"Constituent states",infoboxKicker:"Western coastal and frontier state",flag:{src:"assets/diagrams/burmese-federal-architecture.svg",alt:"Burmese federal architecture",caption:"A Rakhine-led state contains protected northern Muslim districts under unusually close Union and Japanese observation"},
    lead:"Arakan State is the western coastal constituent state formed around a distinct Rakhine Buddhist identity and a protected Muslim north. Its geography, ports, refugee routes, and exposure to the Indian successor system make every local constitutional dispute a wider security problem.",canon:"Rakhine-led statehood, protected northern Muslim districts, separate religious and personal-law guarantees, Union control of coast and frontier security, and recurring violence are established. Borders, capital, official name, district design, and later settlements remain open.",
    sections:[
      {id:"formation",title:"A distinct western state",html:"<p>Coastal geography, Rakhine Buddhist history, and separation from the Irrawaddy core justify constituent statehood rather than ordinary provincial administration.</p>"},
      {id:"government",title:"Rakhine-led institutions",html:"<p>The state government controls ordinary administration, cultural institutions, land, education, and local politics while remaining inside the Union's customs and security system.</p>"},
      {id:"north",title:"Protected northern Muslim district",html:"<p>Northern Muslim communities retain religious institutions, municipal administration, family and personal law, representation, and security guarantees rather than unconditional subordination to a unitary Rakhine government.</p>"},
      {id:"dissatisfaction",title:"No final communal settlement",html:"<p>Rakhine nationalists object to limits on consolidation; Muslim leaders object that district protection remains beneath Rakhine and Bamar authority. Neither treats the arrangement as final.</p>"},
      {id:"union",title:"Coast, ports, and frontier security",html:"<p>The Union retains unusual authority over major ports, coastal surveillance, foreign crossings, and heavy forces because local violence can draw in Indian claimants and wider religious networks.</p>"},
      {id:"spillover",title:"Indian-war spillover",html:"<p>Refugees, arms, militants, smugglers, and political organizations cross the frontier. Strategic observation is heavier than in most constituent states.</p>"},
      {id:"experiment",title:"The sovereign-state problem",html:"<p>Sovereign Arakan immediately reopens the northern district's status. Partition creates another contested border; unity reproduces the dispute inside an international state.</p>"},
      {id:"position",title:"Position in the mature Union",html:"<p>Arakan remains stable on the map and periodically violent on the ground. Thai influence is limited; Japanese and Union security observation remain decisive.</p>"}
    ],related:[{href:"burma.html",kicker:"Federal sovereign",label:"Union of Burma"},{href:"chin-state.html",kicker:"Northern frontier neighbor",label:"Chin State"},{href:"sovereign-states-experiment.html",kicker:"Partition crisis",label:"Sovereign States Experiment"},{href:"india-successors.html",kicker:"Western security context",label:"Indian Successor States"}],facts:[["Government","Rakhine-led constituent state"],["Capital","Open"],["Territory","Western Burmese coast and frontier"],["Protected region","Northern Muslim district"],["District protections","Religion, municipal government, personal law, and representation"],["Union retains","Major ports, coast, and frontier security"],["Principal danger","Indian-war spillover and communal conflict"],["External guarantor","Japan"]]
  }),

  "armed-federalism-burma":burmeseArticle({
    title:"Armed Federalism in Burma",category:"Political and military systems",infoboxKicker:"Union Army, State Guards, and external guarantee",flag:{src:"assets/diagrams/burmese-armed-federalism.svg",alt:"Armed federalism in Burma",caption:"The Union monopolizes heavy force; constituent governments retain infantry institutions; Japan controls escalation"},
    lead:"Armed federalism is the Burmese constitutional system in which the Bamar-led Union Army monopolizes heavy and strategic forces while constituent states retain permanent infantry-based State Guards. Japan controls enough supply, credit, and recognition to prevent both federal conquest and successful unilateral secession; Thailand later manages much daily stabilization.",canon:"The division of forces, legal State Guards, Japanese supply leverage, Thai delegated role, and guardian-republic logic are established. Exact force ceilings, unit lists, officer appointments, mobilization law, and protectorate command treaty remain open.",
    sections:[
      {id:"origin",title:"Legalizing forces Rangoon cannot disarm",html:"<p>The Rangoon Settlement converts several frontier armies into constitutional State Guards because defeating them would prolong war and dissolving them would make autonomy unenforceable.</p>"},
      {id:"union",title:"The Union Army",html:"<p>The central army controls armor, major artillery, combat aviation, arsenals, national communications, officer training, strategic reserves, ports, and the Irrawaddy corridor. Its command culture remains predominantly Bamar.</p>"},
      {id:"guards",title:"The State Guards",html:"<p>Constituent governments retain infantry, scouts, gendarmerie, light mortars, vehicles, pack transport, and local communications. They answer locally in ordinary conditions and enter coordinated Union command in external war.</p>"},
      {id:"limits",title:"Heavy-force restrictions",html:"<p>State Guards may not maintain combat aircraft, major armor, large artillery, or independent foreign supply agreements. Hidden stocks, veteran networks, and smuggling ensure that the legal distinction is never complete.</p>"},
      {id:"japan",title:"Japanese control of escalation",html:"<p>Japan controls advanced ammunition, fuel, aircraft parts, radios, engineering, credit, and diplomatic recognition. Deliveries can slow when Rangoon prepares conquest or disappear when a state attempts secession.</p>"},
      {id:"thailand",title:"Thailand as operating guarantor",html:"<p>Thailand manages eastern ceasefires, crossings, refugee routes, fuel, liaison, and local monitoring. Japan prevents this practical role from becoming unrestricted Thai annexation or separate protectorates.</p>"},
      {id:"guardian",title:"The guardian republic",html:"<p>The central military holds reserve authority over defense, secession, foreign alignment, strategic appointments, and certified emergencies while parliament and civilian ministries retain ordinary law, budgets, and social policy.</p>"},
      {id:"legacy",title:"A constitution that expects another crisis",html:"<p>Armed federalism keeps every government dissatisfied and capable of resistance. Its legitimacy rests on the repeated conclusion that disarmament by one side would be more dangerous than permanent mutual limitation.</p>"}
    ],related:[{href:"burma.html",kicker:"State framework",label:"Union of Burma"},{href:"rangoon-settlement.html",kicker:"Legal origin",label:"Rangoon Settlement"},{href:"burmese-federal-crisis.html",kicker:"First major test",label:"Federal Crisis"},{href:"thai-protectorate-burma.html",kicker:"Mature external guarantee",label:"Thai Protectorate over Burma"}],facts:[["Central force","Union Army"],["Local forces","Seven constituent State Guards"],["Union monopoly","Armor, major artillery, aviation, arsenals, and strategic communications"],["State capabilities","Infantry, scouts, gendarmerie, mortars, and light transport"],["Final supply guarantor","Japan"],["Daily stabilization","Thailand in the mature order"],["Political form","Guardian republic"],["Exact force ceilings","Open"]]
  }),

  "burmese-companion-war":burmeseArticle({
    title:"Burmese Companion War",category:"Wars",eyebrow:"Civil and proxy war · 1948–1953",infoboxKicker:"Founding conflict of the post-British Union",flag:{src:"assets/diagrams/burmese-war-cycle.svg",alt:"Burmese war cycle",caption:"The Companion War is the first and best-dated phase of Burma's recurring constitutional conflict"},
    lead:"The Burmese Companion War was the 1948–1953 conflict in which Britain's protected Burmese rear area fractured during the collapse of India. A Rangoon government, frontier and nationality armies, communist and radical Bamar forces, and Japanese-backed nationalists fought changing regional wars until Japan became broker of a transfer from British protection to associated sovereignty.",canon:"The 1948–1953 period, four broad camps, British retention of Rangoon and strategic corridors, Japanese supply advantage, and negotiated political outcome are established. Battles, commanders, fronts, casualties, and exact opening and closing dates remain open.",
    sections:[
      {id:"background",title:"British Burma as India's rear area",html:"<p>Rangoon, the delta, airfields, railways, and ports absorb evacuation from the Breaking of the Raj. Refugees and stores temporarily strengthen British positions while making the colony more crowded, expensive, and politically foreign.</p>"},
      {id:"camps",title:"Four broad camps",html:"<p>The war joins the British-protected Bamar-led government; frontier and nationality armies; communist and radical Bamar formations; and Japanese-backed nationalists demanding immediate termination of protection.</p>"},
      {id:"core",title:"The core theater",html:"<p>Britain and the recognized government initially retain Rangoon, the delta, main Irrawaddy corridor, railways, airfields, and evacuation ports. Loyalty inside Indian and Burmese formations becomes increasingly uncertain.</p>"},
      {id:"frontiers",title:"Frontier and ethnic theaters",html:"<p>Karen, Shan, Kachin, Chin, Karenni, Mon, Arakanese, and smaller forces secure districts while deciding whether Britain, Rangoon, or Japan offers the least dangerous constitutional future.</p>"},
      {id:"japan",title:"Japan's supply position",html:"<p>Thailand, Malaya, Singapore, the Mekong states, and Bay of Bengal access give Japan a sustainable political and logistical position even after its wartime military defeat in Burma.</p>"},
      {id:"broker",title:"From overthrow to transfer",html:"<p>Tokyo concludes that destruction of Rangoon would create an administrative vacuum. It begins negotiating with the recognized government and frontier leaders while continuing pressure on British protection.</p>"},
      {id:"britain",title:"Negotiated British withdrawal",html:"<p>London accepts organized evacuation and property arrangements because retaining Burma without India would require an expensive inland war. The withdrawal is a strategic defeat but not a second Calcutta Flight.</p>"},
      {id:"outcome",title:"The Rangoon outcome",html:"<p>The war ends through the <a href='rangoon-settlement.html'>1952–1953 settlement package</a>. Japan wins predominance without conquering every district; armed frontiers enter the Union without surrendering their forces.</p>"}
    ],related:[{href:"rangoon-settlement.html",kicker:"Ending settlement",label:"Rangoon Settlement"},{href:"breaking-of-the-raj.html",kicker:"Wider collapse",label:"Breaking of the Raj"},{href:"burma.html",kicker:"Successor state",label:"Union of Burma"},{href:"azad-hind.html",kicker:"Strategic consequence",label:"Azad Hind"}],facts:[["Period","1948–1953"],["Location","Burma"],["Cause","Collapse of the British Indian rear and unresolved Burmese succession"],["Principal camps","Rangoon government, nationality armies, radicals, and Japanese-backed nationalists"],["British strongholds","Rangoon, delta, Irrawaddy corridor, railways, and evacuation ports"],["Japanese advantage","Long-term supply through the mainland Sphere"],["Outcome","Negotiated end of British protection"],["Ending instruments","Rangoon Settlement"]]
  }),

  "rangoon-settlement":burmeseArticle({
    title:"Rangoon Settlement",category:"Treaties and constitutional settlements",eyebrow:"Ceasefire constitution · 1952–1953",infoboxKicker:"End of British protection over Burma",flag:{src:"assets/diagrams/burmese-federal-architecture.svg",alt:"Federal order created at Rangoon",caption:"The settlement preserves one international Union while constitutionalizing unequal states and armed forces"},
    lead:`The Rangoon Settlement was the 1952–1953 package that ended British protection, preserved the <a href='burma.html'>Union of Burma</a>, recognized seven principal constituent nationality arrangements and their State Guards, established Japanese security association, and regulated civilians and property during withdrawal. It was the first Burmese ceasefire constitution rather than a final national settlement.${burmeseCanon}`,canon:`The 1952–1953 date, package character, four principal instruments, end of British protection, one internationally recognized asymmetric Union, seven constituent nationality arrangements, nested autonomy, legal State Guards, Japanese predominance, Thai liaison interests, and separate civilian and property procedures are established.${burmeseCanon} The four short instrument titles are conventional working usage. Enrolled titles, exact texts, dates, signatories, delegates, headquarters, ratification, annexes, force ceilings, claims procedures, and complete implementation chronology remain open.${burmeseExtrapolation}`,
    sections:[
      {id:"character",title:"Character of the settlement",html:`<p>Rangoon is a package of agreements rather than one comprehensive peace treaty. Separate instruments address British withdrawal, the internal federal constitution, Japanese association and security, and the protection of civilians and property. Together they create a state order that none of the instruments could establish alone.${burmeseCanon}</p><p>The settlement stops the original companion war from merging permanently with the Indian Wars. It does not disarm every faction, impose uniform provincial government, or settle whether the Union represents one Burmese nation or an international shell holding several armed national communities.${burmeseCanon}</p>`},
      {id:"background",title:"Background in the Companion War",html:`<p>Britain recovers Burma late in the Second World War and retains it under protection in 1947. Rangoon, the delta, the lower Irrawaddy, principal railways, airfields, and evacuation ports become Britain's eastern rear area as India collapses, receiving civilians, troops, refugees, offices, stores, and retreating formations.${burmeseCanon}</p><p>The <a href='burmese-companion-war.html'>Burmese Companion War of 1948–1953</a> fractures that overloaded system among the British-protected Bamar-led government, frontier and nationality armies, communist and radical Bamar forces, and Japanese-backed nationalists demanding an end to protection. Alliances vary by region and year rather than forming two stable camps.${burmeseCanon}</p>`},
      {id:"negotiation",title:"Negotiation from exhaustion",html:`<p>Britain can defend important centers but cannot pacify Burma after India ceases to be a secure rear. Japan can sustain clients through Thailand, Malaya, Singapore, the Mekong states, and the Bay of Bengal, yet does not want to destroy Rangoon and inherit direct administration of the whole country.${burmeseCanon}</p><p>The central Bamar government cannot cheaply disarm the frontier; the frontier armies cannot conquer the riverine core; and Thailand cannot absorb the eastern states without alarming Japan and other Burmese actors. Negotiation becomes possible because every participant can continue fighting but none can obtain an acceptable complete victory.${burmeseCanon}</p>`},
      {id:"interests",title:"Participants and negotiated interests",html:`<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Participant</th><th>Principal objective</th><th>Settlement return</th></tr></thead><tbody><tr><td>Rangoon government</td><td>End British protection while preserving the state and central core</td><td>International continuity, capital, common ministries, and Union authority</td></tr><tr><td>Constituent nationality authorities</td><td>Protection from Bamar absorption and recognition of local government</td><td>Constituent status, State Guards, language, land, religion, and administration</td></tr><tr><td>Japan</td><td>Predominance without direct reconquest or partition</td><td>Security association, missions, access, mediation, and supply leverage</td></tr><tr><td>Britain</td><td>Orderly withdrawal and protection of connected populations and claims</td><td>Evacuation, residence, property, and compensation procedures</td></tr><tr><td>Thailand</td><td>Stable western frontier and recognized influence</td><td>Commercial and liaison roles without annexation</td></tr></tbody></table></div><p>No party receives its maximum program. The settlement works because each receives more than continued war offers and because Japan can make renewed escalation materially difficult.${burmeseCanon}</p>`},
      {id:"chronology",title:"Negotiating sequence, 1952–1953",html:`<p>By 1952 Japan is shifting from sponsorship of overthrow toward sponsorship of transfer: the existing Burmese state may survive if British protection ends and Japanese association replaces it. Britain increasingly accepts organized withdrawal as preferable to an inland war lacking a governable Indian base.${burmeseCanon}</p><p>The agreements are concluded across 1952–53, stabilize the central core by 1953, and permit Burma to appear internationally as a newly independent Japanese-associated Union. Exact conference dates, negotiating sessions, signature order, provisional application, and ratification remain open.${burmeseCanon}</p>`},
      {id:"instruments",title:"Four principal instruments",html:`<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Conventional short title</th><th>Subject</th><th>Principal effect</th></tr></thead><tbody><tr><td><a href='anglo-burmese-termination-agreement.html'>Anglo–Burmese Termination Agreement</a></td><td>End of British protection</td><td>Transfers remaining authority and organizes military and civilian withdrawal</td></tr><tr><td><a href='federal-articles-rangoon.html'>Federal Articles of Rangoon</a></td><td>Internal constitution</td><td>Recognizes the Union, constituent governments, nested autonomy, and State Guards</td></tr><tr><td><a href='japanese-burmese-association-security-treaty.html'>Japanese–Burmese Association and Security Treaty</a></td><td>External guarantee and security</td><td>Creates Japanese missions, access, mediation, and strategic association</td></tr><tr><td><a href='civilian-protection-property-convention-burma.html'>Civilian Protection and Property Convention</a></td><td>Persons and claims</td><td>Provides evacuation, residence, title, and compensation procedures</td></tr></tbody></table></div><p>The titles describe established subjects but remain conventional working labels. The enrolled names, article numbers, signatories, annexes, and exact legal relationship among the instruments have not been fixed.${burmeseExtrapolation}</p>`},
      {id:"termination",title:"Termination of British protection",html:`<p>The withdrawal instrument ends protection without dissolving Burmese state continuity. Remaining British authority is transferred, forces and protected civilians receive an organized departure framework, and the Union's sovereignty cannot be described solely as a gift of Japanese recognition.${burmeseCanon}</p><p>London loses its Burmese position but avoids a second uncontrolled flight comparable to the collapse around Calcutta. Withdrawal proceeds through ports, airfields, railways, and river transport under procedures whose detailed timetable and retained facilities remain open.${burmeseCanon}</p>`},
      {id:"articles",title:"Federal Articles and the asymmetric Union",html:`<p>The Federal Articles recognize one international Union, a directly governed Bamar core, seven principal constituent nationality arrangements, and protected districts nested within or across them. Authority is divided by bargain rather than by a uniform constitutional template.${burmeseCanon}</p><p>Rangoon retains foreign representation, principal customs and currency functions, the major ports and transport spine, and the common ministries. Constituent governments receive differing powers over language, education, religion, land, ordinary policing, taxation, and civil administration.${burmeseCanon}</p>`},
      {id:"constituents",title:"Principal constituent arrangements",html:`<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Arrangement</th><th>Basis of recognition</th><th>Persistent constitutional problem</th></tr></thead><tbody><tr><td>Shan</td><td>Principalities, territorial institutions, armed forces, and deep internal federalism</td><td>Wa, Pa-O, Palaung, Kokang, and strategic-corridor autonomy</td></tr><tr><td>Kachin</td><td>Military institutions, chiefs, missions, terrain, and northern resources</td><td>Armed autonomy and control of resource districts</td></tr><tr><td>Chin</td><td>District councils, chiefs, churches, and frontier defense</td><td>Administrative weakness and Indian spillover</td></tr><tr><td>Karenni</td><td>Compact territorial and princely identity</td><td>Small scale and dependence upon external guarantees</td></tr><tr><td>Karen</td><td>Southeastern territorial state plus protected communities elsewhere</td><td>Large Karen populations outside the recognized state</td></tr><tr><td>Mon</td><td>Coastal language, historical, religious, and municipal institutions</td><td>Central control of ports, railways, and military facilities</td></tr><tr><td>Arakan</td><td>Rakhine identity and distinct coastal geography</td><td>Protected Muslim communities and the Indian frontier</td></tr></tbody></table></div><p>The table states the seven principal arrangements without fixing every boundary, office, or district schedule. Their unequal histories and mixed populations are precisely why the Union cannot be divided into identical units.${burmeseCanon}</p>`},
      {id:"nested",title:"Nested autonomy and protected communities",html:`<p>Naga, Wa, Pa-O, Palaung, Kokang, and other communities may receive autonomous districts, councils, local police or scouts, language and school rights, customary land protection, and restrictions on outside settlement within a constituent state or the Bamar core.${burmeseCanon}</p><p>Federalism therefore extends downward, with weaker and more conditional guarantees at each level. The design prevents a newly recognized state from reproducing Rangoon's centralism against its own internal minorities, but it also creates overlapping claims and multiple channels of appeal.${burmeseCanon}</p>`},
      {id:"armed",title:"State Guards and armed federalism",html:`<p>The settlement legalizes constituent State Guards because Rangoon cannot disarm them cheaply. They retain infantry, scouts, police, mortars, light vehicles, local communications, and internal-security authority, while the Union controls armor, major artillery, combat aviation, arsenals, strategic communications, and the principal officer system.${burmeseCanon}</p><p>This division permits local self-defense without granting each state a complete conventional army. Hidden stocks, veteran networks, smugglers, and political patrons limit the paper settlement, but sustained heavy war remains dependent upon supply outside any one frontier government.${burmeseCanon}</p>`},
      {id:"japan",title:"Japanese association and reserve supremacy",html:`<p>Japan guarantees Burma's external frontier, gains military missions and strategic access, and becomes the final mediator of constitutional security disputes. Burma enters the Japanese-associated system while retaining its flag, government, citizenship, and international personality.${burmeseCanon}</p><p>Tokyo's decisive power is control of modern ammunition, fuel, aircraft, communications, heavy weapons, development credit, transport, and diplomatic recognition. It need not command every battalion: slowing supply can prevent Rangoon or a State Guard from converting a local crisis into a sustained modern war.${burmeseCanon}</p>`},
      {id:"thailand",title:"Thai interest without annexation",html:`<p>Thailand receives recognized commercial, intelligence, religious, border, and liaison roles along the eastern frontier but no sovereignty over Shan, Karen, or Mon territory. Japan wants Bangkok influential enough to assist stabilization and too constrained to become hegemonic across mainland Southeast Asia.${burmeseCanon}</p><p>The arrangement marks the beginning of Thailand's growing administrative role. The Federal Crisis enlarges that role, and decades of repeated breakdown eventually produce a Thai security protectorate beneath ultimate Japanese guarantee.${burmeseCanon}</p>`},
      {id:"civilians",title:"Civilian protection and property",html:`<p>British, Anglo-Burmese, Indian, Chinese, and other vulnerable urban or mobile communities receive procedures for evacuation, continued residence, property, title, or compensation. The object is to prevent massacre and another uncontrolled imperial flight during the transfer of authority.${burmeseCanon}</p><p>The instrument is transitional rather than a general bill of rights. It can register persons and claims without eliminating communal violence, disputed land, wartime requisition, discrimination, or the insecurity produced by later Burmese wars.${burmeseCanon}</p>`},
      {id:"economy",title:"Transport and economic geography",html:`<p>The Union is preserved partly because its economic regions cannot be separated cleanly. Frontier states require Irrawaddy ports, Rangoon finance, central railways, and coastal shipping; the core requires frontier timber, minerals, roads, border access, and local security.${burmeseCanon}</p><p>Common authority over customs and strategic transport coexists with local power over land, labor, and administration. Japanese firms operate through ministries, State Guards, port authorities, local governments, development bodies, and Thai partners rather than replacing the Burmese political order with direct corporate rule.${burmeseCanon}</p>`},
      {id:"implementation",title:"Implementation",html:`<p>Implementation requires ministries, constituent governments, State Guard liaison, Japanese missions, withdrawal offices, claims bodies, port and railway authorities, translators, and local administrations to act on different instruments at the same time.${burmeseExtrapolation}</p><p>The package works best where the central state, a recognized local authority, and the guarantor agree on jurisdiction. It is weakest where mixed populations, disputed guards, transport corridors, resources, or nested districts give several institutions plausible legal claims to the same place.${burmeseExtrapolation}</p>`},
      {id:"why-union",title:"Why the Union is preserved",html:`<p>Japan rejects both a unitary Bamar conquest and a complete partition into many sovereign clients. One associated Union supplies strategic depth against the Indian war zone, limits Thai expansion, preserves shared ports and transport, and avoids creating separate defense and subsidy systems for every nationality government.${burmeseCanon}</p><p>The settlement also establishes a wider Sphere precedent: recognition of national culture does not automatically grant unlimited external sovereignty. Burma survives because its peoples agree less on common nationhood than on the danger of every available partition.${burmeseCanon}</p>`},
      {id:"regional",title:"Regional consequences",html:`<p>Stabilization of the core by 1953 separates the Burmese settlement from the continuing Indian Wars and enables Burma to appear as a Japanese-associated state. Japanese attention and material, however, remain tied to implementing the fragile Union rather than being available without limit for <a href='azad-hind.html'>Azad Hind</a>.${burmeseCanon}</p><p>The later Federal Crisis disrupts the Burma–Assam supply corridor and helps end Azad Hind's best chance at eastern and northern victory. The Rangoon package therefore reshapes India even though it was negotiated to end a Burmese war.${burmeseCanon}</p>`},
      {id:"limits",title:"Constitutional limits",html:`<p>Recognition does not decide taxation, central appointments, education standards, Buddhist public symbolism, resource control, railway authority, State Guard integration, or the location of ultimate political power. Every attempt to make the emergency Union behave like a normal centralized state reopens the fear of Bamar consolidation.${burmeseCanon}</p><p>The settlement is accumulated community by community. That flexibility ends the first war, but it leaves no single rule for resolving claims among the center, a constituent state, a protected district, an armed organization, and an external guarantor.${burmeseCanon}</p>`},
      {id:"legacy",title:"First settlement, not last",html:`<p>The <a href='burmese-federal-crisis.html'>1954–1956 Federal Crisis</a> begins almost immediately when Rangoon tries to standardize administration and command. Later conflicts test deeper federalism, a Sovereign States Experiment, renewed union, and finally Thai daily supervision.${burmeseCanon}</p><p>Despite those failures, later governments continue to argue through the Rangoon categories: one international Burma, protected nationality institutions, armed local authority, common strategic systems, and an outside guarantee against both conquest and secession. The settlement fails as final peace while enduring as the constitutional language of every successor arrangement.${burmeseCanon}</p>`},
      {id:"record",title:"Documentary status",html:`<p>The four-instrument architecture and its substantive fields are established, but the documents have not been reconstructed as legal texts. Conventional short titles should not be presented as verified enrolled titles, and no precise signatory list, signature hall, article numbering, or ratification sequence is fixed.${burmeseExtrapolation}</p><p>The article therefore records the political and constitutional settlement rather than inventing treaty quotations. Detailed provisions remain bounded by the dedicated instrument articles and future authorial decisions.${burmeseExtrapolation}</p>`}
    ],related:[{href:"burmese-companion-war.html",kicker:"Preceding conflict",label:"Burmese Companion War"},{href:"burma.html",kicker:"Constitutional state",label:"Union of Burma"},{href:"anglo-burmese-termination-agreement.html",kicker:"British withdrawal",label:"Anglo–Burmese Termination Agreement"},{href:"federal-articles-rangoon.html",kicker:"Federal constitution",label:"Federal Articles of Rangoon"},{href:"japanese-burmese-association-security-treaty.html",kicker:"External guarantee",label:"Japanese–Burmese Association and Security Treaty"},{href:"civilian-protection-property-convention-burma.html",kicker:"Civilian settlement",label:"Civilian Protection and Property Convention"},{href:"armed-federalism-burma.html",kicker:"Military order",label:"Armed Federalism"},{href:"burmese-state-guards.html",kicker:"Constituent forces",label:"Burmese State Guards"},{href:"japanese-military-mission-burma.html",kicker:"Security implementation",label:"Japanese Military Mission in Burma"},{href:"internal-protected-association-burma.html",kicker:"Civilian federal doctrine",label:"Internal Protected Association"},{href:"burmese-federal-crisis.html",kicker:"First major failure",label:"Federal Crisis"},{href:"azad-hind.html",kicker:"Indian strategic consequence",label:"Azad Hind"},{href:"thailand.html",kicker:"Regional stabilizer",label:"Kingdom of Thailand"},{href:"geacps.html",kicker:"Sphere setting",label:"Greater East Asia Co-Prosperity Sphere"}],facts:[["Period","1952–1953"],["Form","Four-instrument settlement package"],["Principal outcome","End of British protection"],["State outcome","One internationally recognized asymmetric Union"],["Principal constituent arrangements","Seven"],["Sub-state system","Nested autonomous districts and protected communities"],["Armed settlement","Legal constituent State Guards"],["Common military monopoly","Heavy weapons, aviation, arsenals, and strategic communications"],["External guarantor","Japan"],["Thai position","Commercial and liaison role; no annexation"],["British outcome","Organized withdrawal and civilian/property procedures"],["Instrument titles","Conventional short titles; enrolled titles open"],["Immediate successor crisis","Burmese Federal Crisis, 1954–1956"]]
  }),

  "burmese-federal-crisis":burmeseArticle({
    title:"Burmese Federal Crisis",category:"Political crises and wars",eyebrow:"First post-Rangoon constitutional crisis · 1954–1956",infoboxKicker:"Failure of early federal consolidation",flag:{src:"assets/diagrams/burmese-war-cycle.svg",alt:"Burmese war cycle",caption:"The Federal Crisis follows almost immediately after the Rangoon Settlement"},
    lead:`The Burmese Federal Crisis was the 1954–1956 confrontation produced when Rangoon tried to turn the emergency ceasefire Union created by the <a href='rangoon-settlement.html'>Rangoon Settlement</a> into a functioning centralized state. Taxation, language, education, appointments, resources, transport, and State Guard integration each had an administrative rationale; together they appeared to the frontier as Bamar consolidation.${burmeseCanon}`,canon:`The 1954–1956 period, centralizing policy complex, frontier mobilization, Japanese intervention, deeper federal outcome, growing Thai role, disruption of the Burma–Assam ammunition corridor, and resulting loss of Azad Hind's last plausible final offensive are established.${burmeseCanon} Exact governments, opening decree, campaigns, fronts, battles, leaders, force totals, casualties, armistice, and formal settlement title remain open. Operational sequencing below the strategic level is connective reconstruction.${burmeseExtrapolation}`,
    sections:[
      {id:"scope",title:"Nature of the crisis",html:`<p>The Federal Crisis is the first near-collapse of post-protection Burma. It begins as a dispute over how an emergency constitution should administer ordinary government and escalates when several constituent authorities mobilize rather than accept a combined central program.${burmeseCanon}</p><p>It is more than a cabinet or court dispute but less completely defined than the later Second Burmese War. Fighting, armed standoffs, interrupted transport, disputed deployments, and external intervention occur across several regions, while the exact campaign sequence remains open.${burmeseExtrapolation}</p>`},
      {id:"cause",title:"From ceasefire to administration",html:`<p>The 1952–53 settlement can stop unrestricted war more easily than collect taxes, standardize records, operate railways, appoint officials, manage resources, or control armed institutions. Its flexibility depends upon treating different regions differently, while a functioning central ministry depends upon rules that apply across regions.${burmeseCanon}</p><p>Rangoon therefore confronts a structural dilemma. Leaving every emergency bargain untouched weakens the Union's ability to govern; converting those bargains into one normal administrative order appears to the frontier as withdrawal of the autonomy that made peace possible.${burmeseCanon}</p>`},
      {id:"policies",title:"The centralizing program",html:`<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Policy field</th><th>Central rationale</th><th>Frontier interpretation</th></tr></thead><tbody><tr><td>State Guard integration</td><td>One chain of command and common readiness</td><td>Disarmament by stages</td></tr><tr><td>Standard taxation</td><td>Fund common government and transport</td><td>Transfer of local revenue to the Bamar core</td></tr><tr><td>Burmese-language education</td><td>Common administration and citizenship</td><td>Cultural assimilation</td></tr><tr><td>Buddhist public institutions</td><td>National legitimacy and social provision</td><td>Bamar religious predominance over Christian or local institutions</td></tr><tr><td>Central appointments</td><td>Professional and accountable administration</td><td>Replacement of local authority by Rangoon clients</td></tr><tr><td>Resource administration</td><td>National development and export coordination</td><td>Extraction from frontier land</td></tr><tr><td>Railway and road authority</td><td>Secure strategic movement and a common market</td><td>Military access through protected territory</td></tr></tbody></table></div><p>No single proposal necessarily requires abolition of federalism. Their cumulative effect appears to move taxation, culture, appointments, land, transport, and armed power in the same centralizing direction.${burmeseCanon}</p>`},
      {id:"constitutional",title:"Competing constitutional readings",html:`<p>Rangoon reads the Federal Articles as a transition from wartime bargains toward common institutions. Constituent governments read them as permanent guarantees that the Union exists only because armed national communities consent to share limited powers.${burmeseCanon}</p><p>Nested autonomous districts complicate both positions. A Shan, Karen, Kachin, or Arakan government can defend its own autonomy against Rangoon while facing similar claims from protected communities inside its territory. The crisis is therefore not a simple center-versus-frontier conflict.${burmeseCanon}</p>`},
      {id:"actors",title:"Political and military actors",html:`<p>The <a href='u-nu-civilian-government.html'>civilian government</a>, central ministries, and the <a href='union-army-burma.html'>Union Army</a> do not necessarily pursue identical versions of consolidation. Civil administrators seek revenue and records; officers emphasize transport, heavy weapons, communications, and federal integrity.${burmeseExtrapolation}</p><p>Shan, Karen, Kachin, and other constituent authorities mobilize directly or tolerate militias acting in their name. State Guards, local police, party organizations, religious networks, chiefs, transport officials, and insurgent remnants overlap without producing one frontier coalition or unified command.${burmeseCanon}</p>`},
      {id:"escalation",title:"Escalation, 1954–1956",html:`<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Phase</th><th>Development</th><th>Strategic effect</th></tr></thead><tbody><tr><td>1954</td><td>Central administrative proposals and local refusals generate mobilization, appeals, and contested implementation</td><td>The Rangoon bargain becomes a live security dispute</td></tr><tr><td>1955</td><td>Several regional crises threaten to merge; transport and supply through Burma become unreliable</td><td>Japan diverts advisers, aviation, engineers, communications, and ammunition eastward</td></tr><tr><td>1956</td><td>External pressure and exhaustion prevent decisive consolidation or secession</td><td>Deeper guarantees preserve the Union while the central normal-state project recedes</td></tr></tbody></table></div><p>The three-stage sequence is established at strategic scale. Exact monthly dates, first clashes, fronts, operations, and settlement sessions remain open.${burmeseCanon}</p>`},
      {id:"frontier",title:"Frontier mobilization",html:`<p>State Guards secure roads, depots, administrative centers, passes, ferries, and radio sites; central forces defend the Irrawaddy and strategic corridors; irregulars exploit the space between recognized commands. Several regional fronts risk becoming one general war.${burmeseExtrapolation}</p><p>Mobilization does not imply that every nationality government seeks immediate secession. Many leaders use armed readiness to compel enforcement of the existing settlement or to resist a particular appointment, tax, school rule, garrison, or transport order.${burmeseCanon}</p>`},
      {id:"army",title:"Union Army and military guardianship",html:`<p>The Union Army controls the systems that distinguish a common army from a State Guard: armor, major artillery, combat aviation, arsenals, strategic communications, and the principal officer structure. The crisis strengthens its claim to reserve authority over federal integrity.${burmeseCanon}</p><p>Force cannot by itself normalize the frontier. An army victory over one guard may require occupation of a mixed district, threaten other states, and consume Japanese-controlled ammunition. The result is a stronger constitutional role for military guardianship rather than an accepted centralized monopoly over all armed life.${burmeseCanon}</p>`},
      {id:"heavy-weapons",title:"Heavy-weapons and escalation controls",html:`<p>The <a href='burmese-heavy-weapons-regime.html'>heavy-weapons regime</a> becomes Japan's principal means of limiting escalation. State Guards can sustain light infantry and local security from existing stocks, but extended artillery, armor, aviation, advanced communications, and high ammunition expenditure require external supply.${burmeseCanon}</p><p>Tokyo can slow deliveries, inspect transfers, condition access to fuel and transport, or authorize limited reinforcement without occupying every disputed district. This reserve supremacy prevents either central conquest or unilateral secession from becoming decisive.${burmeseCanon}</p>`},
      {id:"japan",title:"Japanese intervention",html:`<p>Japan pressures Rangoon to halt comprehensive consolidation while pressuring constituent governments to reject secession and disarm unauthorized formations. It moves advisers, aircraft, engineers, transport, communications, ammunition, and political attention into the Burmese emergency.${burmeseCanon}</p><p>The intervention defends the Union created at Rangoon rather than one side's constitutional reading. Tokyo accepts stronger federal guarantees because losing Burma, partitioning it, or conducting a direct reconquest would each impose greater strategic cost.${burmeseCanon}</p>`},
      {id:"thailand",title:"Thailand enters the settlement machinery",html:`<p>Thailand's border routes, refugee control, commercial networks, and relationships with Shan, Karen, and other eastern actors make it a practical stabilization partner. Bangkok can observe and influence sectors that Japanese missions or Rangoon ministries reach only indirectly.${burmeseCanon}</p><p>The crisis enlarges Thailand's role without granting sovereignty or a general right of intervention. Japan balances Thai access against Rangoon's fear of encirclement and the constituent states' fear that one external patron will replace another.${burmeseCanon}</p>`},
      {id:"corridor",title:"Breakdown of the Burma–Assam corridor",html:`<p>The <a href='burma-assam-ammunition-corridor.html'>Burma–Assam corridor</a> carries Japanese materiel toward Azad Hind through inland routes chosen partly to reduce exposure to hostile maritime interdiction. The Federal Crisis interrupts transport, consumes capacity inside Burma, and redirects Japanese attention and supplies.${burmeseCanon}</p><p>The decisive shortage is ammunition rather than the instantaneous removal of every weapon already delivered. Azad Hind continues advancing through much of 1955 on accumulated stocks, while advisers and commanders recognize that replenishment is failing behind the front.${burmeseCanon}</p>`},
      {id:"azad-hind",title:"Azad Hind's lost offensive",html:`<p><a href='azad-hind.html'>Azad Hind</a> reaches the high-water mark of its Indian campaign with a plausible chance to defeat Congress India in the east and north. By 1956 its ammunition and transport position no longer supports the same operational tempo.${burmeseCanon}</p><p>Ill-advised final attacks fail, and <a href='congress-india.html'>Congress India</a> drives Azad Hind back toward Bengal, Calcutta, and eastern depots where remaining stocks can support defense. Burma's breakdown helps end the last plausible final offensive and contributes to the wider freezing of the Indian Wars.${burmeseCanon}</p>`},
      {id:"memory-india",title:"The Burmese diversion in Indian memory",html:`<p>Azad Hind does not primarily accuse Japan of intentional betrayal. Its political and military memory identifies Burma as the crisis that consumed the decisive campaigning season and broke the supply route when victory appeared attainable.${burmeseCanon}</p><p>The phrase “Burmese diversion” becomes a durable accusation whenever resources are spent on an allied emergency rather than Indian reunification. That grievance helps keep Azad Hind an associate of Japan rather than a fully integrated Sphere member.${burmeseCanon}</p>`},
      {id:"settlement",title:"Deeper formal federalism",html:`<p>The 1956 resolution strengthens State Guards, language and land protections, revenue arrangements, and direct appeal to external guarantors. Rangoon survives as the capital and international government while its attempt to turn the ceasefire constitution into a uniform normal state fails.${burmeseCanon}</p><p>The settlement clarifies methods of consultation, liaison, supply control, and crisis containment without resolving ultimate sovereignty. Exact instrument titles and legal clauses remain open.${burmeseCanon}</p>`},
      {id:"aftermath",title:"Immediate aftermath",html:`<p>Central ministries retain enough authority to operate foreign policy, customs, principal transport, and common institutions. Constituent governments emerge with stronger evidence that mobilization and external appeal can protect autonomy.${burmeseCanon}</p><p>Japan and Thailand gain more permanent roles in monitoring security and movement. The Union becomes governable through negotiated exceptions, military liaison, and external reserve power rather than through one uncontested constitutional hierarchy.${burmeseCanon}</p>`},
      {id:"legacy",title:"Prelude to later Burmese wars",html:`<p>The crisis resolves an administrative program, not the disagreement over what Burma is. A later dispute over the Union itself brings several State Guards into simultaneous war and leads to the <a href='second-burmese-war.html'>Second Burmese War</a> and the Sovereign States Experiment.${burmeseCanon}</p><p>Every later settlement inherits the 1954–56 lesson: central government cannot abolish armed particularism cheaply, but external patrons will not accept unlimited secession. Repeated failure eventually persuades Japan to delegate daily security supervision to Thailand in the 1990s.${burmeseCanon}</p>`},
      {id:"record",title:"Open operational record",html:`<p>The crisis's dates, policy causes, strategic progression, external intervention, constitutional result, and Indian consequence are established. No settled source fixes the opening decree, named campaigns, commanders, force totals, front lines, battles, casualties, armistice text, or complete government chronology.${burmeseCanon}</p><p>Descriptions of checkpoints, depots, liaison, and regional movement explain what the established institutions require; they do not constitute a finalized battle history.${burmeseExtrapolation}</p>`}
    ],related:[{href:"rangoon-settlement.html",kicker:"Failed foundation",label:"Rangoon Settlement"},{href:"federal-articles-rangoon.html",kicker:"Disputed constitution",label:"Federal Articles of Rangoon"},{href:"burma.html",kicker:"State preserved",label:"Union of Burma"},{href:"u-nu-civilian-government.html",kicker:"Civil government",label:"U Nu Civilian Government"},{href:"union-army-burma.html",kicker:"Central armed institution",label:"Union Army of Burma"},{href:"burmese-state-guards.html",kicker:"Constituent forces",label:"Burmese State Guards"},{href:"armed-federalism-burma.html",kicker:"Security outcome",label:"Armed Federalism"},{href:"burmese-heavy-weapons-regime.html",kicker:"Escalation control",label:"Burmese Heavy-Weapons Regime"},{href:"japanese-military-mission-burma.html",kicker:"External intervention",label:"Japanese Military Mission in Burma"},{href:"burmese-crisis-escalation-control.html",kicker:"Containment system",label:"Burmese Crisis Escalation Control"},{href:"thailand.html",kicker:"Emerging stabilization partner",label:"Kingdom of Thailand"},{href:"burma-assam-ammunition-corridor.html",kicker:"Supply route broken",label:"Burma–Assam Ammunition Corridor"},{href:"azad-hind-lost-victory.html",kicker:"Indian consequence",label:"Azad Hind's Lost Victory"},{href:"azad-hind.html",kicker:"Client deprived",label:"Azad Hind"},{href:"congress-india.html",kicker:"Indian beneficiary",label:"Congress India"},{href:"second-burmese-war.html",kicker:"Later escalation",label:"Second Burmese War"}],facts:[["Period","1954–1956"],["Worst phase","1955–1956"],["Principal issue","Central administration versus protected autonomy"],["Central policies","Tax, education, appointments, transport, resources, and State Guard integration"],["Major resisting states","Shan, Karen, Kachin, and others"],["Central armed institution","Union Army"],["External strategic mediator","Japan"],["Expanded stabilization role","Thailand"],["Regional supply effect","Burma–Assam ammunition corridor disrupted"],["Indian consequence","Azad Hind's last plausible final offensive fails"],["Burmese outcome","Deeper federal guarantees and military guardianship"],["Exact campaigns and settlement title","Open"]]
  }),

  "second-burmese-war":burmeseArticle({
    title:"Second Burmese War",category:"Wars",eyebrow:"General federal war · later 1960s",infoboxKicker:"War over the nature of the Union",flag:{src:"assets/diagrams/burmese-war-cycle.svg",alt:"Burmese war cycle",caption:"The Second Burmese War is established in sequence, while its exact date and trigger remain open"},
    lead:"The Second Burmese War was the later-1960s general conflict in which several Burmese State Guards mobilized over the nature of the Union rather than one disputed administrative policy. Japan and Thailand prevented Bamar conquest, refused unilateral secession, and accepted a temporary Sovereign States Experiment when federal autonomy appeared exhausted.",canon:"The war's later-1960s placement, general federal character, simultaneous State Guard mobilization, Japanese–Thai intervention, and sovereign-state outcome are established. Exact dates, trigger, leaders, fronts, battles, casualties, and armistice remain open.",
    sections:[
      {id:"background",title:"The exhausted federal bargain",html:"<p>The Rangoon system survives the first crisis but leaves every government armed and doubtful that emergency autonomy can become permanent constitutional order.</p>"},
      {id:"trigger",title:"An open immediate trigger",html:"<p>Possible triggers include the presidency, capital, revenue, army command, succession to a strong leader, or a constitutional attempt to end frontier privileges. No single option is yet fixed.</p>"},
      {id:"mobilization",title:"Simultaneous State Guard mobilization",html:"<p>Several constituent forces mobilize at once. Rangoon declares the Union ungovernable; frontier governments describe common institutions as Bamar rule under another name.</p>"},
      {id:"union",title:"Limits of Union heavy power",html:"<p>The central army can threaten corridors and capitals but cannot conquer every mountain frontier without sustained Japanese fuel, aviation, ammunition, and finance.</p>"},
      {id:"external",title:"Japanese and Thai intervention",html:"<p>Thailand manages eastern borders and liaison while Japan controls heavy supply and recognition. Both block federal conquest and reject independent foreign alignments.</p>"},
      {id:"stalemate",title:"No accepted federal victory",html:"<p>A military ceasefire cannot answer whether the Union belongs equally to the states or is the Bamar national government with attached autonomies.</p>"},
      {id:"outcome",title:"Permission to separate",html:"<p>Japan accepts the <a href='sovereign-states-experiment.html'>temporary international recognition</a> of eight principal nationality governments under common transit and defense machinery.</p>"},
      {id:"legacy",title:"The road to interstate war",html:"<p>Formal sovereignty converts internal disputes into borders, customs posts, minority treaties, and interstate mobilization. The experiment soon produces the War of the Burmese States.</p>"}
    ],related:[{href:"burmese-federal-crisis.html",kicker:"Earlier warning",label:"Federal Crisis"},{href:"sovereign-states-experiment.html",kicker:"War-ending settlement",label:"Sovereign States Experiment"},{href:"armed-federalism-burma.html",kicker:"Military background",label:"Armed Federalism"},{href:"burmese-wars.html",kicker:"Conflict sequence",label:"Burmese Wars and Settlements"}],facts:[["Period","Later 1960s; exact dates open"],["Conflict type","General federal war"],["Principal issue","Nature and governability of the Union"],["Immediate trigger","Open"],["Principal forces","Union Army and multiple State Guards"],["External interveners","Japan and Thailand"],["Outcome","Sovereign States Experiment"],["Battles and casualties","Open"]]
  }),

  "sovereign-states-experiment":burmeseArticle({
    title:"Sovereign States Experiment",category:"Constitutional settlements",eyebrow:"Temporary Burmese international partition · dates open",infoboxKicker:"Eight-state answer to failed federalism",flag:{src:"assets/diagrams/sovereign-states-experiment.svg",alt:"Structure and contradictions of the Sovereign States Experiment",caption:"Eight governments gain sovereignty while population, transit, minority, and security systems remain common problems"},
    lead:"The Sovereign States Experiment was the temporary dissolution or radical reduction of the Union after the Second Burmese War. Bamar Burma, Shan, Kachin, Chin, Karen, Karenni, Mon, and Arakan received international statehood while Japan required common clearing, transit, military restrictions, foreign-base rules, and collective defense.",canon:"The eight principal states, temporary sovereign status, common systems, internal minority problem, and eventual failure are established. Exact dates, legal titles, capital, council, borders, flags, and recognition procedure remain open.",
    sections:[
      {id:"creation",title:"Sovereignty after exhausted federalism",html:"<p>Japan accepts the argument that armed autonomy has failed and permits the principal governments to test whether international separation can remove the question of who rules Burma.</p>"},
      {id:"states",title:"The eight states",html:"<p>Bamar Burma, Shan, Kachin, Chin, Karen, Karenni, Mon, and Arakan control citizenship, internal law, education, police, taxation, government, and national guards.</p>"},
      {id:"common",title:"Common machinery survives",html:"<p>Currency clearing, customs transit, rail and river access, military ceilings, foreign bases, collective defense, and relations with the wider Sphere remain coordinated through a common Burmese council.</p>"},
      {id:"bamar",title:"Bamar inheritance",html:"<p>Bamar Burma retains Rangoon, much of the army, the central bank, bureaucracy, ports, and the largest market. Other states suspect that its government treats sovereignty as a temporary route back to reunion.</p>"},
      {id:"minorities",title:"Minorities inside the new nations",html:"<p>Wa, Pa-O, Ta’ang/Palaung, Kokang, delta Karen, and northern Arakanese Muslim communities reject the idea that one newly sovereign nationality may absorb them.</p>"},
      {id:"corridors",title:"Ports, roads, rivers, and capitals",html:"<p>Karen and Mon states dispute southeastern access; every government depends on shared railways and rivers; placing the common council in Rangoon makes Bamar leadership appear permanent.</p>"},
      {id:"failure",title:"Border and transit breakdown",html:"<p>Customs seizures, road closures, minority militias, freight detention, tolls, and disputed villages escalate because international sovereignty gives ordinary administrative acts strategic meaning.</p>"},
      {id:"legacy",title:"Proof against simple partition",html:"<p>The <a href='war-of-burmese-states.html'>ensuing war</a> demonstrates that formal separation cannot untangle mixed geography. Later unions cite the experiment as the reason one international Burmese personality must survive.</p>"}
    ],related:[{href:"second-burmese-war.html",kicker:"Preceding conflict",label:"Second Burmese War"},{href:"war-of-burmese-states.html",kicker:"Terminal conflict",label:"War of the Burmese States"},{href:"bamar-union-core.html",kicker:"Largest successor",label:"Bamar Union Core"},{href:"burma.html",kicker:"Reconstituted framework",label:"Union of Burma"}],facts:[["Date","Open; after the later-1960s Second Burmese War"],["International states","Eight"],["Members","Bamar, Shan, Kachin, Chin, Karen, Karenni, Mon, and Arakan"],["National powers","Citizenship, internal law, education, police, taxation, and guards"],["Common systems","Clearing, transit, defense, military ceilings, and foreign bases"],["Common council location","Open"],["Outcome","War of the Burmese States"],["Long-term judgment","Formal partition failed"]]
  }),

  "war-of-burmese-states":burmeseArticle({
    title:"War of the Burmese States",category:"Wars",eyebrow:"Interstate Burmese conflict · dates open",infoboxKicker:"Collapse of the Sovereign States Experiment",flag:{src:"assets/diagrams/sovereign-states-experiment.svg",alt:"Contradictions leading to the War of the Burmese States",caption:"Borders, transit, minorities, and inherited central institutions turn separation into interstate conflict"},
    lead:"The War of the Burmese States was the conflict that ended the Sovereign States Experiment. Border posts, roads, river tolls, freight trains, protected districts, ports, and minority militias drew the eight governments into mobilization until Japan and Thailand secured the strategic skeleton of the country and reconstituted one Burmese international framework.",canon:"The war's place after the sovereign-state experiment, escalation pattern, inability of any state to conquer the whole region, Japanese–Thai stabilization, and reconstitution of one international personality are established. Exact dates, belligerent coalitions, battles, casualties, and final union title remain open.",
    sections:[
      {id:"incidents",title:"Administrative incidents become international crises",html:"<p>A customs post seized, road closed, train detained, toll imposed, militia armed, or village occupied can no longer be treated as an internal police matter.</p>"},
      {id:"mobilization",title:"Mobilization to avoid local defeat",html:"<p>States mobilize because failure to defend one border or minority claim could destroy the credibility of their newly recognized sovereignty.</p>"},
      {id:"limits",title:"No power capable of total conquest",html:"<p>Several governments can threaten capitals, railways, ports, or food supply. None possesses enough heavy force or administrative reach to conquer every frontier.</p>"},
      {id:"appeals",title:"Competing appeals to Japan and Thailand",html:"<p>Every government presents itself as victim and requests recognition, fuel, ammunition, transport, mediation, or intervention. Thai frontier preferences increase mutual suspicion.</p>"},
      {id:"stabilization",title:"Japanese–Thai stabilization force",html:"<p>External forces secure Rangoon, principal airfields, the Irrawaddy system, eastern crossings, ports, and railway junctions without attempting conquest of every mountain district.</p>"},
      {id:"settlement",title:"Reconstitution of common power",html:"<p>One international personality, common defense, transit, and currency machinery return beneath exceptionally strong internal governments. The final name may be Union of Burmese States or Burmese Associated Union; neither is fixed.</p>"},
      {id:"after",title:"A hierarchy of later conflicts",html:"<p>Local security crises, regional wars, and rare Union crises continue. Thailand normally mediates first; Japan intervenes when common currency, alignment, Rangoon, or the Union's survival is threatened.</p>"},
      {id:"legacy",title:"Why sovereignty did not solve geography",html:"<p>The war becomes the central argument against renewed partition: the peoples can receive flags and citizenship without acquiring separate ports, rivers, roads, minorities, or security systems.</p>"}
    ],related:[{href:"sovereign-states-experiment.html",kicker:"Failed settlement",label:"Sovereign States Experiment"},{href:"burma.html",kicker:"Reconstituted state",label:"Union of Burma"},{href:"thai-protectorate-burma.html",kicker:"Later security settlement",label:"Thai Protectorate over Burma"},{href:"burmese-wars.html",kicker:"Conflict sequence",label:"Burmese Wars and Settlements"}],facts:[["Date","Open"],["Preceding order","Sovereign States Experiment"],["Belligerents","Burmese nationality states; coalitions open"],["Immediate disputes","Borders, transit, tolls, minorities, and corridors"],["Strategic interveners","Japan and Thailand"],["External secured nodes","Rangoon, airfields, Irrawaddy, ports, crossings, and rail junctions"],["Outcome","Reconstituted common Burmese framework"],["Final union title","Open"]]
  }),

  "thai-protectorate-burma":burmeseArticle({
    title:"Thai Protectorate over Burma",category:"Protectorates and security systems",eyebrow:"Security protectorate · mid-1990s onward",infoboxKicker:"Delegated Japanese stabilization order",flag:{src:"assets/diagrams/burmese-armed-federalism.svg",alt:"External guarantee in Burmese armed federalism",caption:"Thailand manages common security above surviving Burmese institutions while Japan retains the final strategic guarantee"},
    lead:"The Thai protectorate over Burma is the security order created when Japan authorized Thailand to intervene in Burma's final large federal crisis during the mid-1990s. Burma remains a formally sovereign member of the Greater East Asian system and its Bamar, Shan, Kachin, Chin, Karen, Karenni, Mon, and Arakanese governments retain domestic institutions. Thailand nevertheless controls common security, heavy weapons, foreign alignment, strategic transport, and final ordinary arbitration under an ultimate Japanese guarantee. The arrangement is commonly described by the working name <a href='burmese-protection-mandate.html'>Burmese Protection Mandate</a>.",canon:"The mid-1990s crisis and intervention, Japanese authorization, formal Burmese sovereignty, survival of constituent governments and local institutions, Thai control of common security, heavy weapons, alignment, strategic transport and arbitration, the High Commission, the Thai security authority, and the final Japanese guarantee are established. Burmese Protection Mandate and the institutional titles are useful working names. Exact dates, initiating crisis, legal instrument, officeholders, deployment totals, bases, budgets, force ceilings, and termination provisions remain open.",
    sections:[
      {id:"background",title:"End of the settlement cycle",html:"<p>The protectorate follows the <a href='burmese-companion-war.html'>Companion War</a>, Rangoon Settlement, Federal Crisis, Second Burmese War, Sovereign States Experiment, and <a href='war-of-burmese-states.html'>War of the Burmese States</a>. Each settlement preserves some combination of union, autonomy, armed nationality governments, and external guarantee. None separates the mixed populations, ports, river system, railways, resource districts, and competing military institutions upon which all of the successor governments depend.</p><p>During a final crisis, conventionally placed around 1994–1997, Tokyo rejects another internally negotiated constitution. The immediate trigger and exact chronology remain open.</p>"},
      {id:"intervention",title:"Japanese authorization and Thai intervention",html:"<p>Thailand has already spent decades monitoring eastern ceasefires, managing refugees, supplying border districts, and supporting Japanese mediation. Japan now authorizes Bangkok to impose rather than merely assist a settlement. During the <a href='thai-intervention-burma.html'>Thai intervention</a>, Thai forces secure Rangoon, Mandalay, principal ports and airfields, the Irrawaddy transport spine, trunk rail junctions, eastern crossings, fuel depots, and heavy-weapons arsenals. They do not attempt permanent occupation of every mountain district or village.</p>"},
      {id:"sovereignty",title:"Sovereignty without strategic freedom",html:"<p>Burma keeps its flag, citizenship, international personality, central ministries, parliament, ordinary courts, Union Army, constituent governments, State Guards, languages, schools, temples, and local laws. It is not annexed to Thailand; Burmese people do not become Thai citizens, the Chakri monarch does not take a Burmese royal title, and there is no general Thai settlement program.</p><p>The reservation is decisive. Burmese institutions cannot independently alter foreign alignment, move major forces between states, obtain unrestricted heavy weapons, or overturn the protected constitutional balance.</p>"},
      {id:"architecture",title:"Mandate institutions",html:"<p>The working constitutional description contains three principal layers. A <a href='thai-high-commission-burma.html'>Thai High Commission in Rangoon</a> supervises common security, diplomacy, budget settlement, transport corridors, inter-state disputes, and appointments to common bodies. A <a href='council-burmese-states.html'>Council of Burmese States</a> gives the nationality governments a common forum. A <a href='thai-security-command-burma.html'>Thai Security Command</a> controls the strategic military system. The formal legal titles, precise competences, and officeholders remain unsettled.</p>"},
      {id:"security",title:"Division of armed authority",html:"<p>Thai authority covers military aviation, principal arsenals, strategic communications, registered heavy weapons, ceasefire observation, and operational movement along the national transport network. The Union Army and State Guards continue to supply infantry, police, scouts, border guards, and most local security. Thai supervision therefore sits above <a href='armed-federalism-burma.html'>Burmese armed federalism</a> rather than replacing every Burmese formation with an occupation force.</p>"},
      {id:"states",title:"Constituent governments under protection",html:"<p>Bamar, Shan, Kachin, Chin, Karen, Karenni, Mon, and Arakanese authorities retain land administration, language policy, religion, schools, policing, local courts, and their registered Guards. They cannot establish foreign bases, acquire unsupervised strategic weapons, secede unilaterally, or use the common transport system for war against another constituent government.</p><p>Rangoon preserves symbolic seniority and the machinery of a sovereign Union, but no longer possesses an uncontested right to convert that machinery into Bamar national rule.</p>"},
      {id:"apex",title:"The external-apex settlement",html:"<p>The protectorate functions because the authority above the nationality governments is openly foreign. A Shan or Karen official accepting a Thai ruling is not conceding that a Bamar government rightfully commands the entire country; a Bamar official is not admitting the sovereignty of a frontier state. The Thai Crown supplies a monarchy-like continuity above the competing governments without legally becoming the Burmese crown.</p><p>This same arrangement impedes a common liberation movement. Each nationality can blame another Burmese faction for making Thai intervention necessary, while fearing that a unified anti-Thai command would restore a rival's domestic supremacy.</p>"},
      {id:"japan",title:"Japanese ultimate guarantee",html:"<p>Japan retains external defense, strategic recognition, major supply, and final review over the mandate's relationship to the wider Sphere. Tokyo prevents outside powers from using the intervention as an opening and prevents Thailand from turning delegated responsibility into annexation or an independent mainland bloc. Japan has transferred the daily burden, not surrendered primacy.</p><p>The protectorate nevertheless marks a <a href='burma-preservationist-break.html'>preservationist break</a>: national institutions remain protected only so long as their coexistence produces a minimally functional strategic order.</p>"},
      {id:"economy",title:"Concessions and corridor development",html:"<p>The <a href='thai-burmese-concession-economy.html'>concession economy</a> gives Thai firms, military-linked enterprises, court interests, Japanese banks, and zaibatsu privileged access to timber, petroleum and gas, gems, minerals, rice, hydropower, ports, construction, and communications. Roads, railways, river ports, pipelines, power projects, and border crossings serve extraction and security simultaneously.</p><p>Burmese governments bargain for royalties, employment, infrastructure, and local contracts. The High Commission can reward cooperation with access and administrative latitude or answer renewed mobilization by restricting funds, transport, and arms.</p>"},
      {id:"thailand",title:"Thailand's western burden",html:"<p>Thai nationalists initially present the intervention as proof that Bangkok can solve a mainland problem Japan failed to master. Administration rapidly consumes officers, police, translators, engineers, railway staff, judges, health services, treasury officials, patronage, and diplomatic attention. Burma makes Thailand wealthier and strategically deeper while tying much of its state capacity to a permanent western emergency.</p><p>This <a href='thailand-burmese-burden.html'>Burmese burden</a> narrows Thai diplomacy inside GEACPS and contributes to the <a href='malayan-autonomy-settlement.html'>late-1990s enlargement of Malayan self-government</a>: Bangkok cannot administer Burma intensively while supervising Malaya on the earlier model.</p>"},
      {id:"sphere",title:"Meaning inside the Sphere",html:"<p>Other associated states read the intervention as evidence that Japanese patience has limits. Tokyo argues that the protectorate preserves Burmese governments and cultures; critics answer that preservation beneath foreign strategic command remains imperial rule. Governments elsewhere become more cautious about allowing local disputes to threaten common transport, corporate systems, or security guarantees.</p><p><a href='azad-hind-lost-victory.html'>Azad Hind</a> treats the intervention as confirmation of its older grievance that Burmese disorder consumed Japan's chance to support Indian reunification. It remains a bilateral associate of Japan rather than accepting common obligations with Burma.</p>"},
      {id:"assessment",title:"Durability without reconciliation",html:"<p>The protectorate reduces operational-scale warfare because no Burmese government can mobilize the strategic systems required to conquer the others. It does not create a common national loyalty or persuade Burmese peoples that Rangoon, Bangkok, or Tokyo is neutral. By the setting's present, Burma is a functioning but openly unequal protected order: harder to abandon, harder to overthrow collectively, and no closer to resolving the historical argument over who ought to govern it.</p>"}
    ],related:[{href:"burmese-protection-mandate.html",kicker:"Institutional order",label:"Burmese Protection Mandate"},{href:"burma.html",kicker:"Protected sovereign",label:"Union of Burma"},{href:"final-burmese-crisis.html",kicker:"Founding emergency",label:"Final Burmese Crisis"},{href:"thai-intervention-burma.html",kicker:"Founding operation",label:"Thai Intervention in Burma"},{href:"thai-high-commission-burma.html",kicker:"Executive supervision",label:"Thai High Commission"},{href:"armed-federalism-burma.html",kicker:"Internal security system",label:"Armed Federalism"},{href:"thailand.html",kicker:"Protecting power",label:"Kingdom of Thailand"},{href:"thailand-burmese-burden.html",kicker:"Metropolitan consequence",label:"Thailand's Burmese Burden"}],facts:[["Established","Mid-1990s; exact date open"],["Working constitutional name","Burmese Protection Mandate"],["Protected state","Union of Burma"],["Protecting power","Kingdom of Thailand"],["Ultimate guarantor","Empire of Japan"],["Burma retains","Sovereignty, citizenship, governments, languages, and local institutions"],["Thailand controls","Common security, heavy weapons, alignment, strategic transport, and arbitration"],["Principal supervisory bodies","High Commission, Council of Burmese States, and Security Command; working titles"],["Annexation or mass Thai settlement","None"],["International alignment","GEACPS"]]
  })
});

